# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"
require_relative "contract_example_helpers"
require_relative "../../support/timekeeping/local_owner_arrange"

RSpec.describe TimekeepingContract::LocalOwnerClient do
  include TimekeepingContractExampleHelpers

  let(:timekeeping_arrange) { TimekeepingContract::LocalOwnerArrange.new(private_key: timekeeping_key_pair) }
  let(:timekeeping_client) { described_class.new(public_key: timekeeping_key_pair.public_key) }

  # "The shared entry API contract and the idempotency contract for entries pass against the local owner"
  it "local owner client creates through the local owner with exactly the contract response fields and refuses an unknown token" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    token = timekeeping_arrange.token_for(user)

    created = create_entry(company, token, entry_body(project:))

    expect(created.status).to eq(201)
    expect(created.body.keys).to match_array(TimekeepingContract.load(:entry_api).dig("response", "entry_fields"))
    expect(created.body["duration"]).to eq(90.0)
    expect(Timekeeping::LocalEntry.where(company_id: company, user_id: user).count).to eq(1)
    expect(Timekeeping::LocalOutboxEntry.where(company_id: company).count).to eq(1)

    refused = create_entry(company, "not-a-token", entry_body(project:))
    expect(refused.status).to eq(401)
    expect(Timekeeping::LocalEntry.where(company_id: company).count).to eq(1)
  end
end
